for bi, (ename, theme, note, titles) in enumerate(BATCHES):
    assert len(titles) == 20, ename
    f1 = 601 + bi * 20
    f2 = f1 + 19
    lines = []
    lines.append(f"#### UNX-E4-{ename} · {theme}（UNX-E4-E{f1:03d}–E{f2:03d} · 20 条）")
